/**
 * Contract data types of media — part of the data schema of the whole system.
 * The UI types of the gallery and the server-side processing types stay in
 * media/types/media.d.ts.
 */

import type { TBricksMediaImageFormat } from './config';

/**
 * Parameters of raster optimization on upload.
 *
 * One type for the client and the server: the client puts these three fields into
 * the multipart form and the server reads them from there — that is, this is the
 * shape of a request rather than a detail of either side. The type used to be
 * declared twice (and the format three times), and the copies drifted apart
 * silently.
 */
export interface IBricksMediaOptimization {
    format: TBricksMediaImageFormat;
    quality: number;
    maxWidth: number;
}

/**
 * The effective bounds of the "maximum width" — shared by the input field and by
 * the upload endpoint. Computed from the value in the config, hence not constants.
 */
/**
 * The media settings of `runtimeConfig.public.bricksMedia` (the `bricks.media` option of
 * the module). Every field is optional: an installation that says nothing keeps the
 * defaults of the runtime.
 */
export interface IBricksPublicMediaConfig {
    imageHosts?: string[];
}

export interface IMediaMaxWidthBounds {
    min: number;
    max: number;
}

export interface IMediaItem {
    id: number;
    url: string;
    filename: string;
    alt: string;
    size: number;
    uploadedAt: string;
    mimeType: string;
    /** null — a file with no category: it is visible under the "All" filter only */
    category: string | null;
    thumbnailUrl?: string;
    svgContent: string | null;
    /**
     * Pixel dimensions of the raster; null — unknown (an svg, a video, an external
     * URL or a file uploaded before the dimensions started being stored).
     */
    width: number | null;
    height: number | null;
    /**
     * Downscaled variants for progressive loading: preview (~480px) and mock
     * (~32px). null — there is no such variant (an svg, a video, an external URL, a
     * file uploaded before the variants appeared); in that case the consumer has to
     * show the full file right away rather than nothing.
     */
    previewUrl: string | null;
    mockUrl: string | null;
}

export interface IMediaUpdateMetaRequest {
    filename?: string;
    alt?: string;
}

export interface IMediaListResponse {
    success: boolean;
    items: IMediaItem[];
    error?: string;
}

export interface IMediaUpdateCategoryRequest {
    /** null clears the category off the file */
    category: string | null;
}

export type TMediaGalleryContext = 'manager' | 'publish' | 'properties';

/**
 * A category of the media library. The `slug` travels into
 * `bricks_media.category` and into the gallery filter, while the `label` is the
 * caption entered by the user (there is nothing to translate it into).
 *
 * There are no preset categories: the whole set is created by the user, and any of
 * them can be deleted — the files of a deleted one stay in the media library
 * without a category.
 */
export interface IMediaCategory {
    id: number;
    slug: string;
    label: string;
    sortOrder: number;
}

export interface IMediaCategoryListResponse {
    success: boolean;
    items: IMediaCategory[];
    error?: string;
}

export interface IMediaCategoryCreateRequest {
    /** Caption entered by the user; the slug is generated by the server */
    label: string;
}

/**
 * Response of a category deletion: how many files it was cleared off. The number
 * has to be shown — "the category was deleted" and "12 files were left without a
 * category" are different events.
 */
export interface IMediaCategoryDeleteResponse {
    success: boolean;
    clearedCount: number;
}
